#!/usr/bin/env bash
# Builds a Play-uploadable release AAB. android/ is regenerated by prebuild (gitignored),
# so everything that prebuild can't express (SDK path, release signing) is re-applied here.
# Needs ~/.keystores/jpan-upload.properties (storeFile/storePassword/keyAlias/keyPassword).
set -euo pipefail
cd "$(dirname "$0")/.."

PROPS="$HOME/.keystores/jpan-upload.properties"
[ -f "$PROPS" ] || { echo "missing $PROPS"; exit 1; }
SDK_DIR="${ANDROID_HOME:-/opt/homebrew/share/android-commandlinetools}"

npx expo prebuild -p android --clean --no-install
echo "sdk.dir=$SDK_DIR" > android/local.properties
echo >> android/gradle.properties
echo "android.packagingOptions.excludes=META-INF/*.md" >> android/gradle.properties
# Play flags apps with <25% obfuscated DEX; turn on R8 shrink/obfuscate + resource shrinking.
echo "android.enableMinifyInReleaseBuilds=true" >> android/gradle.properties
echo "android.enableShrinkResourcesInReleaseBuilds=true" >> android/gradle.properties
# kuromoji reads its dictionary via class-relative resource paths, and ml-features is looked
# up by name: renaming either breaks pronunciation/OCR at runtime, so keep them intact.
cat >> android/app/proguard-rules.pro <<'RULES'
-keep class com.atilika.kuromoji.** { *; }
-keep class expo.modules.mlfeatures.** { *; }
RULES
# Gradle/AGP here don't work on the system default JDK 25; pin 17 if available.
JDK17="$(/usr/libexec/java_home -v 17 2>/dev/null | grep -m1 -E "(jdk|openjdk)-?17" || true)"
[ -n "$JDK17" ] && echo "org.gradle.java.home=$JDK17" >> android/gradle.properties

python3 - "$PROPS" <<'PY'
import sys,re
props=dict(l.strip().split('=',1) for l in open(sys.argv[1]) if '=' in l)
p='android/app/build.gradle'
s=open(p).read()
block=f"""    signingConfigs {{
        release {{
            storeFile file('{props['storeFile']}')
            storePassword '{props['storePassword']}'
            keyAlias '{props['keyAlias']}'
            keyPassword '{props['keyPassword']}'
        }}
"""
s=s.replace("    signingConfigs {\n",block,1)
# release buildType: swap the debug signing for the upload key
i=s.index("        release {\n            // Caution")
j=s.index("signingConfig signingConfigs.debug",i)
s=s[:j]+"signingConfig signingConfigs.release"+s[j+len("signingConfig signingConfigs.debug"):]
open(p,'w').write(s)
PY

(cd android && ./gradlew bundleRelease)
AAB=android/app/build/outputs/bundle/release/app-release.aab
mkdir -p dist && cp "$AAB" dist/japan-menu-translator.aab
echo "OK: dist/japan-menu-translator.aab"
